tw.local.originalTeam = new tw.object.Team();
tw.local.originalTeam.members = new tw.object.listOf.String();
//tw.local.originalTeam.members[0] = "odchubexemkr07";
//tw.local.originalTeam.members[1] = "odchubexemkr10";
//tw.local.originalTeam.members[2] = "odchubexemkr20";
//tw.local.originalTeam.members[3] = "odchubexemkr31";
//tw.local.originalTeam.members[4] = "odchubexemkr38";
//tw.local.originalTeam.members[5] = "odchubexemkr59";
//tw.local.originalTeam.managerTeam = "Managers";
//tw.local.originalTeam.name = "ODC EXE HUB";

tw.local.filteredTeam = new tw.object.Team();
tw.local.filteredTeam.members = new tw.object.listOf.String();
tw.local.filteredTeam.managerTeam = tw.local.originalTeam.managerTeam;
tw.local.filteredTeam.name = tw.local.originalTeam.name;

var users = tw.system.org.findRoleByName(tw.local.groupName).allUsers;
	
log.info("users::: "+ users);
	for (var i = 0; i < users.listLength ; i++)
	{
		tw.local.filteredTeam.members[i] = users[i].name;
	}
	
tw.local.TEAM_MANAGER = ""+  tw.epv.TeamsNameBPM.HUB_EXE_Manager;
tw.local.FILTER_BRANCH = tw.local.groupName.split('_')[3];
if(tw.local.groupName.split('_')[5] == "MKR"){
	//tw.local.TEAM_NAME = ""+tw.epv.TeamsNameBPM.HUB_EXE_MKR;
	tw.local.PARENT_TEAM_NAME = ""+tw.epv.BPMTeamsNamesReassign.idc_hub_exe_Maker;
}else{
	//tw.local.TEAM_NAME = ""+tw.epv.TeamsNameBPM.HUB_EXE_CHKR;
	tw.local.PARENT_TEAM_NAME = ""+tw.epv.BPMTeamsNamesReassign.idc_hub_exe_Checker;
}

tw.local.TEAM_NAME = tw.local.groupName;

